        if let Some(kw) = self.next_if_keyword() {
            Ok(Some(match kw {
                Keyword::Cross => ast::JoinType::Cross,
                Keyword::Inner => ast::JoinType::Inner,
                Keyword::Left => ast::JoinType::Left,
                Keyword::Right => ast::JoinType::Right,
